def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r ** 3
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0))) for t in sites]
    elements = [t.get('element') for t in sites]
    nearest = [math.inf] * n
    bonds = s.get('neighbors', ())
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and occ[b['j']] > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    total = 0.0
    hetero = 0.0
    for b in bonds:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            total += w
            if elements[i] != elements[j]:
                hetero += w
    amounts = {}
    for i in range(n):
        e = elements[i]
        amounts[e] = amounts.get(e, 0.0) + occ[i]
    norm = sum(occ)
    if total <= 0 or norm <= 0:
        return 0.0
    random_fraction = 1.0 - sum((x / norm) ** 2 for x in amounts.values())
    return float(hetero / total - random_fraction)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        count = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and count is not None and math.isfinite(count):
            total += x * count
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0
